//! `CoordgenTemplates`, `sketcherMinimizer::compare` and friends: coordinates of difficult ring systems taken from
//! templates (`data/templates.txt`, converted from the autogenerated `CoordgenTemplates.cpp` by
//! `tools/gen_coordgen_templates.py`), the Morgan scores used to match them, and the 2x2 alignment matrix.

use std::sync::OnceLock;

use super::maths::{MACROCYCLE, PointF, round_to_two_decimal_digits, same_side};
use super::model::{AtomId, BondId, Model};

/// a template molecule: coordinates (normalized to bond length 1) and bonds between atom indices
#[derive(Debug, Clone)]
pub struct Template {
    pub atomic_numbers: Vec<i32>,
    pub coordinates: Vec<PointF>,
    pub bonds: Vec<(usize, usize, i32)>,
}

/// `normalizeTemplate`: scales the most common bond length to 1
fn normalize_template(t: &mut Template) {
    let mut dds: Vec<f32> = Vec::new();
    let mut ns: Vec<i32> = Vec::new();
    for &(a, b, _) in &t.bonds {
        let v = t.coordinates[a] - t.coordinates[b];
        let dd = v.x * v.x + v.y * v.y;
        let mut found = false;
        for j in 0..dds.len() {
            if f64::from(dd) * 0.9 < f64::from(dds[j]) && f64::from(dd) * 1.1 > f64::from(dds[j]) {
                ns[j] += 1;
                found = true;
                break;
            }
        }
        if !found {
            dds.push(dd);
            ns.push(1);
        }
    }
    if !dds.is_empty() {
        let mut max_i = 0;
        for i in 0..ns.len() {
            if ns[i] > ns[max_i] {
                max_i = i;
            }
        }
        let f = dds[max_i].sqrt();
        for c in &mut t.coordinates {
            *c = *c / f;
        }
    }
}

/// the 82 built-in templates (`coordgen_templates()` followed by `normalizeTemplate`)
pub fn templates() -> &'static [Template] {
    static TEMPLATES: OnceLock<Vec<Template>> = OnceLock::new();
    TEMPLATES.get_or_init(|| {
        let text = include_str!("data/templates.txt");
        let mut out = Vec::new();
        let mut lines = text.lines();
        while let Some(head) = lines.next() {
            let h: Vec<usize> = head[2..].split(' ').map(|v| v.parse().unwrap()).collect();
            let mut t = Template {
                atomic_numbers: Vec::new(),
                coordinates: Vec::new(),
                bonds: Vec::new(),
            };
            for _ in 0..h[0] {
                let f: Vec<&str> = lines.next().unwrap().split(' ').collect();
                t.atomic_numbers.push(f[0].parse().unwrap());
                let mut p = PointF::new(f[1].parse().unwrap(), f[2].parse().unwrap());
                // `setCoordinates` rounds
                p.round(2);
                t.coordinates.push(p);
            }
            for _ in 0..h[1] {
                let f: Vec<&str> = lines.next().unwrap().split(' ').collect();
                t.bonds.push((
                    f[0].parse().unwrap(),
                    f[1].parse().unwrap(),
                    f[2].parse().unwrap(),
                ));
            }
            normalize_template(&mut t);
            out.push(t);
        }
        out
    })
}

/// `morganScores`: iterated neighbor sums over the bonds (given as index pairs); returns the number of iterations and
/// the scores of the last improving one
pub fn morgan_scores(n_atoms: usize, bonds: &[(usize, usize)]) -> (i32, Vec<i32>) {
    if n_atoms < 2 {
        return (0, Vec::new());
    }
    let mut old_scores = vec![1i32; n_atoms];
    let mut new_scores = vec![0i32; n_atoms];
    let mut old_ties = n_atoms;
    let mut n = 0;
    loop {
        n += 1;
        for &(i1, i2) in bonds {
            new_scores[i1] += old_scores[i2];
            new_scores[i2] += old_scores[i1];
        }
        let mut ordered = new_scores.clone();
        ordered.sort();
        let new_ties = ordered.windows(2).filter(|w| w[0] == w[1]).count();
        if new_ties < old_ties {
            old_ties = new_ties;
            old_scores = new_scores.clone();
        } else {
            break;
        }
    }
    (n, old_scores)
}

/// `svd` of a 2x2 matrix as the sketcher uses it (`a`, `U`, `Sig`, `V` row major)
pub fn svd(a: [f32; 4]) -> ([f32; 4], [f32; 4], [f32; 4]) {
    let a1 = [a[0], a[2], a[1], a[3]];
    let su = [
        a[0] * a1[0] + a[1] * a1[2],
        a[0] * a1[1] + a[1] * a1[3],
        a[2] * a1[0] + a[3] * a1[2],
        a[2] * a1[1] + a[3] * a1[3],
    ];
    let phi = (0.5 * f64::from((su[1] + su[2]).atan2(su[0] - su[3]))) as f32;
    let cphi = round_to_two_decimal_digits(phi.cos());
    let sphi = round_to_two_decimal_digits(phi.sin());
    let u = [-cphi, -sphi, -sphi, cphi];
    let sw = [
        a1[0] * a[0] + a1[1] * a[2],
        a1[0] * a[1] + a1[1] * a[3],
        a1[2] * a[0] + a1[3] * a[2],
        a1[2] * a[1] + a1[3] * a[3],
    ];
    let theta = (0.5 * f64::from((sw[1] + sw[2]).atan2(sw[0] - sw[3]))) as f32;
    let (ctheta, stheta) = (theta.cos(), theta.sin());
    let w = [ctheta, -stheta, stheta, ctheta];
    let su_sum = su[0] + su[3];
    let su_dif = ((su[0] - su[3]) * (su[0] - su[3]) + 4.0 * su[1] * su[2]).sqrt();
    let sig = [
        ((su_sum + su_dif) * 0.5).sqrt(),
        0.0,
        0.0,
        ((su_sum - su_dif) * 0.5).sqrt(),
    ];
    let u1 = [u[0], u[2], u[1], u[3]];
    let u1a = [
        u1[0] * a[0] + u1[1] * a[2],
        u1[0] * a[1] + u1[1] * a[3],
        u1[2] * a[0] + u1[3] * a[2],
        u1[2] * a[1] + u1[3] * a[3],
    ];
    let mut s = [
        u1a[0] * w[0] + u1a[1] * w[2],
        u1a[0] * w[1] + u1a[1] * w[3],
        u1a[2] * w[0] + u1a[3] * w[2],
        u1a[2] * w[1] + u1a[3] * w[3],
    ];
    for v in &mut s {
        *v = round_to_two_decimal_digits(*v);
    }
    let sign1 = if s[0] < 0.0 { -1.0f32 } else { 1.0 };
    let sign2 = if s[3] < 0.0 { -1.0f32 } else { 1.0 };
    let c = [sign1, 0.0, 0.0, sign2];
    let mut v = [
        w[0] * c[0] + w[1] * c[2],
        w[0] * c[1] + w[1] * c[3],
        w[2] * c[0] + w[3] * c[2],
        w[2] * c[1] + w[3] * c[3],
    ];
    for x in &mut v {
        *x = round_to_two_decimal_digits(*x);
    }
    (u, sig, v)
}

/// `alignmentMatrix`: the rotation (row major 2x2) that best maps `points` onto `reference`
pub fn alignment_matrix(reference: &[PointF], points: &[PointF]) -> [f32; 4] {
    let mut a = [0.0f32; 4];
    for (r, p) in reference.iter().zip(points) {
        a[0] += r.x * p.x;
        a[1] += r.y * p.x;
        a[2] += r.x * p.y;
        a[3] += r.y * p.y;
    }
    let (u, _sig, v) = svd(a);
    [
        v[0] * u[0] + v[1] * u[1],
        v[0] * u[2] + v[1] * u[3],
        v[2] * u[0] + v[3] * u[1],
        v[2] * u[2] + v[3] * u[3],
    ]
}

struct Search<'a> {
    size: usize,
    matrix: &'a [bool],
    template_coordinates: &'a [PointF],
    mol_bonds: &'a [Vec<usize>],
    template_bonds: &'a [Vec<usize>],
    mol_cis_trans_chains: &'a [Vec<usize>],
    mol_is_cis: &'a [bool],
}

impl Search<'_> {
    /// `checkIdentity`: depth first assignment of molecule atoms to template atoms
    fn check_identity(
        &self,
        mut solution: Vec<usize>,
        new_sol: usize,
        found: &mut Option<Vec<usize>>,
    ) {
        solution.push(new_sol);
        let size = self.size;
        if solution.len() == size {
            let mut ok = true;
            for (i, chain) in self.mol_cis_trans_chains.iter().enumerate() {
                let p = |k: usize| self.template_coordinates[solution[chain[k]]];
                if self.mol_is_cis[i] != same_side(p(0), p(3), p(1), p(2)) {
                    ok = false;
                    break;
                }
            }
            if ok {
                *found = Some(solution);
            }
            return;
        }
        for i in 0..size {
            if found.is_some() {
                break;
            }
            if !self.matrix[solution.len() * size + i] {
                continue;
            }
            if solution.contains(&i) {
                continue;
            }
            let mut check = true;
            for &mol_bond in &self.mol_bonds[solution.len()] {
                check = false;
                let (mut high, mut low) = (i, solution[mol_bond]);
                if low > high {
                    std::mem::swap(&mut low, &mut high);
                }
                if self.template_bonds[high].contains(&low) {
                    check = true;
                }
                if !check {
                    break;
                }
            }
            if check {
                self.check_identity(solution.clone(), i, found);
            }
        }
    }
}

impl Model {
    /// `sketcherMinimizer::compare`: the atom mapping (molecule atom -> template atom) if the atoms and bonds are
    /// the template. The atoms must carry their index in `general_use_n`.
    pub fn compare_with_template(
        &self,
        atoms: &[AtomId],
        bonds: &[BondId],
        templ: &Template,
    ) -> Option<Vec<usize>> {
        if atoms.len() != templ.coordinates.len() {
            return None;
        }
        let size = atoms.len();
        let mol_pairs: Vec<(usize, usize)> = bonds
            .iter()
            .map(|&b| {
                (
                    self.atoms[self.bonds[b].start_atom].general_use_n as usize,
                    self.atoms[self.bonds[b].end_atom].general_use_n as usize,
                )
            })
            .collect();
        let temp_pairs: Vec<(usize, usize)> = templ.bonds.iter().map(|&(a, b, _)| (a, b)).collect();
        let (mol_iter, mol_scores) = morgan_scores(size, &mol_pairs);
        let (templ_iter, temp_scores) = morgan_scores(size, &temp_pairs);
        if mol_iter != templ_iter {
            return None;
        }
        // filled by the double bond stereo check once the CIP ranking exists
        let mol_cis_trans_chains: Vec<Vec<usize>> = Vec::new();
        let mol_is_cis: Vec<bool> = Vec::new();
        for &bond in bonds {
            let b = &self.bonds[bond];
            if b.bond_order != 2 || b.ignore_ze {
                continue;
            }
            let ok = b
                .rings
                .iter()
                .all(|&r| self.rings[r].atoms.len() >= MACROCYCLE);
            if !ok {
                continue;
            }
            let find_n = |atom: AtomId, other: AtomId| -> Option<AtomId> {
                self.atoms[atom]
                    .neighbors
                    .iter()
                    .copied()
                    .filter(|&n| n != other)
                    .find(|n| atoms.contains(n))
            };
            let start_n = find_n(b.start_atom, b.end_atom);
            let end_n = find_n(b.end_atom, b.start_atom);
            if start_n.is_some() && end_n.is_some() {
                // needs the CIP priorities (`startAtomCIPFirstNeighbor`), which are ported with the stereo stage
                unimplemented!(
                    "double bonds in macrocycles of a template ring system need the CIP ranking"
                );
            }
        }
        let mut mol_bonds: Vec<Vec<usize>> = vec![Vec::new(); size];
        let mut template_bonds: Vec<Vec<usize>> = vec![Vec::new(); size];
        for &(i1, i2) in &mol_pairs {
            if i1 < i2 {
                mol_bonds[i2].push(i1);
            } else {
                mol_bonds[i1].push(i2);
            }
        }
        for &(i1, i2) in &temp_pairs {
            if i1 < i2 {
                template_bonds[i2].push(i1);
            } else {
                template_bonds[i1].push(i2);
            }
        }
        let mut matrix = vec![false; size * size];
        for ma in 0..size {
            for ta in 0..size {
                if mol_scores[ma] == temp_scores[ta] {
                    matrix[ma * size + ta] = true;
                }
            }
        }
        let search = Search {
            size,
            matrix: &matrix,
            template_coordinates: &templ.coordinates,
            mol_bonds: &mol_bonds,
            template_bonds: &template_bonds,
            mol_cis_trans_chains: &mol_cis_trans_chains,
            mol_is_cis: &mol_is_cis,
        };
        let mut found = None;
        for i in 0..size {
            if !matrix[i] {
                continue;
            }
            search.check_identity(Vec::new(), i, &mut found);
            if found.is_some() {
                break;
            }
        }
        found
    }
}

#[cfg(test)]
mod tests {
    use super::super::testutil::build;
    use super::*;
    use std::fmt::Write;

    /// the templates, Morgan scores, template matches and alignment matrices must be the ones of the C++ code
    /// (`tests/data/coordgen_templates.txt`, driver `tools/coordgen_drv/tmpl.cpp`)
    #[test]
    fn templates_match_cpp() {
        let text = include_str!("../../../../../tests/data/coordgen_templates.txt");
        let ts = templates();
        assert_eq!(ts.len(), 82);
        let mut bad: Vec<String> = Vec::new();
        let mut n_mols = 0;
        let mut rest = text;
        for (i, t) in ts.iter().enumerate() {
            let (line, tail) = rest.split_once('\n').unwrap();
            rest = tail;
            let pairs: Vec<(usize, usize)> = t.bonds.iter().map(|&(a, b, _)| (a, b)).collect();
            let (it, scores) = morgan_scores(t.coordinates.len(), &pairs);
            let mut got = format!(
                "T {i} {} {} iter {it} scores",
                t.coordinates.len(),
                t.bonds.len()
            );
            for s in scores {
                write!(got, " {s}").unwrap();
            }
            got.push_str(" coords");
            for c in &t.coordinates {
                write!(got, " {:08x} {:08x}", c.x.to_bits(), c.y.to_bits()).unwrap();
            }
            if got != line {
                bad.push(format!("template {i}\nwant {line}\ngot  {got}"));
            }
        }
        for rec in rest.split("$$\n").filter(|r| !r.is_empty()) {
            let end = rec.find("END\n").unwrap() + 4;
            let (input, want) = rec.split_at(end);
            let (mut model, mol) = build(input);
            model.force_update_struct(mol);
            let mut atoms: Vec<usize> = Vec::new();
            let mut bonds: Vec<usize> = Vec::new();
            for &r in &model.molecules[mol].rings.clone() {
                for &a in &model.rings[r].atoms.clone() {
                    if !atoms.contains(&a) {
                        model.atoms[a].general_use_n = atoms.len() as i32;
                        atoms.push(a);
                    }
                }
            }
            for &r in &model.molecules[mol].rings {
                for &b in &model.rings[r].bonds {
                    if !bonds.contains(&b) {
                        bonds.push(b);
                    }
                }
            }
            let pairs: Vec<(usize, usize)> = bonds
                .iter()
                .map(|&b| {
                    (
                        model.atoms[model.bonds[b].start_atom].general_use_n as usize,
                        model.atoms[model.bonds[b].end_atom].general_use_n as usize,
                    )
                })
                .collect();
            let (it, scores) = morgan_scores(atoms.len(), &pairs);
            let mut got = format!("morgan {it}");
            for s in scores {
                write!(got, " {s}").unwrap();
            }
            got.push('\n');
            let mut found = false;
            for (t, templ) in ts.iter().enumerate() {
                if let Some(mapping) = model.compare_with_template(&atoms, &bonds, templ) {
                    write!(got, "match {t}").unwrap();
                    for v in mapping {
                        write!(got, " {v}").unwrap();
                    }
                    got.push('\n');
                    found = true;
                    break;
                }
            }
            if !found {
                got.push_str("match none\n");
            }
            let (s, c) = (0.7f32.sin(), 0.7f32.cos());
            let mut reference = Vec::new();
            let mut pts = Vec::new();
            for (i, &a) in model.molecules[mol].atoms.iter().enumerate().take(12) {
                let p = model.atoms[a].coordinates;
                reference.push(p);
                pts.push(PointF::new(
                    p.x * c + p.y * s + (i % 3) as f32 * 0.37,
                    -p.x * s + p.y * c - (i % 4) as f32 * 0.21,
                ));
            }
            let am = if reference.is_empty() {
                [0.0; 4]
            } else {
                alignment_matrix(&reference, &pts)
            };
            writeln!(
                got,
                "align {:08x} {:08x} {:08x} {:08x}",
                am[0].to_bits(),
                am[1].to_bits(),
                am[2].to_bits(),
                am[3].to_bits()
            )
            .unwrap();
            n_mols += 1;
            if got != want {
                let pos = got
                    .lines()
                    .zip(want.lines())
                    .position(|(a, b)| a != b)
                    .unwrap_or(0);
                bad.push(format!(
                    "{}\nline {pos}\nwant {:?}\ngot  {:?}",
                    input.lines().next().unwrap(),
                    want.lines().nth(pos),
                    got.lines().nth(pos)
                ));
            }
        }
        assert!(n_mols > 100, "{n_mols}");
        assert!(bad.is_empty(), "{} differ; first:\n{}", bad.len(), bad[0]);
    }
}
